let parts = msg.topic.split('/');
let building = parts[1] || "A1";
let floor = parts[2] || "2";
let roomID = parts[3] || "A1-201";

let p = msg.payload;
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch(e) {
        node.error("JSON parse error", msg);
        return null;
    }
}

// Format chuẩn cho node-red-contrib-influxdb (Influx 2.0)
// [fields, tags]
msg.payload = [
    {
        count: Number(p.count !== undefined ? p.count : 0),
        presence: Number(p.presence !== undefined ? p.presence : 0),
        t: Number(p.t !== undefined ? p.t : 0.0),
        rh: Number(p.rh !== undefined ? p.rh : 0.0),
        co2: Number(p.co2 !== undefined ? p.co2 : 400),
        lux: Number(p.lux !== undefined ? p.lux : 0),
        p_w: Number(p.p_w !== undefined ? p.p_w : 0.0),
        e_wh: Number(p.e_wh !== undefined ? p.e_wh : 0.0),
        light: String(p.light || "off"),
        fan: String(p.fan || "off"),
        mode: String(p.mode || "auto"),
        alarm_state: String(p.alarm_state || "NORMAL"),
        alarm_level: Number(p.alarm_level !== undefined ? p.alarm_level : 0)
    },
    {
        building: String(building),
        floor: String(floor),
        room: String(roomID),
        node_type: String(p.node_type || "classroom")
    }
];

msg.measurement = "room_telemetry";
return msg;

let parts = msg.topic.split('/');
let building = parts[1] || "A1";
let floor = parts[2] || "2";
let roomID = parts[3] || "A1-201";

let p = msg.payload;
if (typeof p === 'string') {
    try {
        p = JSON.parse(p);
    } catch(e) {
        p = { type: "EVENT", detail: msg.payload };
    }
}

let eventType = String(p.type || "INFO");
let severity = 0;
if (eventType.includes("ALARM") || eventType === "FIRE" || eventType === "OVERTEMP") {
    severity = 3; // ALARM
} else if (eventType.includes("FAULT")) {
    severity = 2; // FAULT
} else if (eventType.includes("WARNING") || eventType === "OVERCAPACITY" || eventType === "ENERGY_WASTE") {
    severity = 1; // WARNING
}

msg.payload = [
    {
        type: eventType,
        detail: String(p.detail || p.msg || ""),
        val: Number(p.val !== undefined ? p.val : 0),
        severity: severity
    },
    {
        building: String(building),
        floor: String(floor),
        room: String(roomID)
    }
];

msg.measurement = "room_event";
return msg;

let parts = msg.topic.split('/');
let building = parts[1] || "A1";
let floor = parts[2] || "2";
let roomID = parts[3] || "A1-201";

let statusStr = String(msg.payload).trim().toLowerCase();
let isOnline = (statusStr === "online") ? 1 : 0;

msg.payload = [
    {
        online: isOnline,
        state: statusStr
    },
    {
        building: String(building),
        floor: String(floor),
        room: String(roomID)
    }
];

msg.measurement = "room_status";
return msg;

let b = msg.payload.building || "A1";
let f = msg.payload.floor || "2";
let r = msg.payload.room || "A1-201";

let topic = `school/${b}/${f}/${r}/cmd`;
let cmd = {
    timestamp: new Date().toISOString(),
    light: msg.payload.light,
    fan: msg.payload.fan,
    mode: msg.payload.mode,
    ack_alarm: msg.payload.ack_alarm !== undefined ? msg.payload.ack_alarm : false
};

let mqttMsg = {
    topic: topic,
    payload: JSON.stringify(cmd)
};

let httpMsg = {
    payload: {
        status: "OK",
        published_to: topic,
        command: cmd
    },
    req: msg.req,
    res: msg.res
};

return [mqttMsg, httpMsg];
